mapper.codeEditorJavascript:
// ────────────────────────────────────────────────────────────────────────
// Textbau — EIN generischer Renderer für alle drei Register.
// Baut aus den Vorlagen der Landkarte: text (Ops) · vtext (Vertriebler) ·
// ctext (City) und liefert dazu die beiden dynamischen Chat-IDs und die
// Foto-URL. Geldwerte werden nur FORMATIERT, nie gerechnet.
//
// Token-Auflösung: felder (Fachdatensatz) → vfelder → sfelder → ctx
//   {abs Token}      Betrag ohne Vorzeichen (Rückholungen buchen negativ)
//   {Vorname}        erstes Wort aus {Vertriebler}
//   {Saldoabruf}     Vergleich Betrag ggü. Offen, siehe unten
//   {Maps-URL}       aus Store-Name + ⚙ Google Place ID gebaut
//   {leer FELD}…     Zeilen-Modifier, wird vor der Ersetzung ausgewertet
//
// Warum zwei Lesungen desselben Datensatzes: mit returnFieldsByFieldId
// liefern LINK-Felder Record-IDs (rec…), mit cellFormat=string liefern sie
// den Klartext — dafür kommen Geld und Datum dort formatiert statt roh.
// Deshalb: Zahlen/Daten aus der JSON-Lesung, Links aus der Klartext-Lesung.
// ────────────────────────────────────────────────────────────────────────

const felder  = input.felder  || {};
const vfelder = input.vfelder || {};
const sfelder = input.sfelder || {};
const geld    = input.geld    || [];
const ctx     = input.ctx     || {};

const recJ  = input.record      || {};   // Fachdatensatz, JSON
const recT  = input.recordText  || {};   // Fachdatensatz, Klartext
const vertJ = input.vertriebler || {};   // Vertriebler, JSON
const stoT  = input.store       || {};   // Store, Klartext

const vQuelle = String(input.vertrieblerFeld || '');
const sQuelle = String(input.storeFeld || '');
const saldoModus = String(input.saldo || '');

// Ist der Fachdatensatz selbst der Vertriebler bzw. der Store, sind die
// Nachlese-Module leer — dann zeigt die Ebene auf den Fachdatensatz.
const vertriebler = (vQuelle === '*') ? recJ : vertJ;
const storeJ      = (sQuelle === '*') ? recJ : {};
const storeT      = (sQuelle === '*') ? recT : stoT;

const RECID = /^rec[A-Za-z0-9]{14}$/;

function istRecIds(v) {
  if (!Array.isArray(v) || v.length === 0) return false;
  for (let i = 0; i < v.length; i++) {
    if (typeof v[i] !== 'string' || !RECID.test(v[i])) return false;
  }
  return true;
}

function flach(v) {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) {
    return v.map(flach).filter(function (x) { return x !== ''; }).join(', ');
  }
  if (typeof v === 'object') return v.name || v.text || v.filename || '';
  if (typeof v === 'boolean') return v ? 'ja' : '';
  return v;
}

// Rohwert einer Ebene: JSON bevorzugt, bei Link-Feldern der Klartext.
function ausEbene(fid, json, text) {
  const j = json ? json[fid] : undefined;
  if (istRecIds(j)) {
    const t = text ? text[fid] : undefined;
    return (t === undefined || t === null || t === '') ? '' : t;
  }
  if (j === undefined && text) return text[fid];
  return j;
}

function roh(token) {
  if (Object.prototype.hasOwnProperty.call(felder, token)) {
    return ausEbene(felder[token], recJ, recT);
  }
  if (Object.prototype.hasOwnProperty.call(vfelder, token)) {
    return ausEbene(vfelder[token], vertriebler, {});
  }
  if (Object.prototype.hasOwnProperty.call(sfelder, token)) {
    return ausEbene(sfelder[token], storeJ, storeT);
  }
  if (Object.prototype.hasOwnProperty.call(ctx, token)) return ctx[token];
  return undefined;
}

function istLeer(v) {
  if (v === null || v === undefined || v === false) return true;
  if (Array.isArray(v)) return v.length === 0;
  return String(v).trim() === '';
}

function zahl(v) {
  const n = Number(flach(v));
  return isNaN(n) ? null : n;
}

function euro(n) {
  const s = Math.abs(Number(n)).toFixed(2).split('.');
  const t = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (Number(n) < 0 ? '−' : '') + t + ',' + s[1] + ' €';
}

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ── abgeleitete Werte ───────────────────────────────────────────────────

const vertrieblerName = String(flach(roh('Vertriebler')) || '');
const vorname = vertrieblerName.split(' ')[0] || '';

const storeName  = String(flach(ausEbene(sfelder['Store'], storeJ, storeT)) || '');
const placeId    = String(flach(ausEbene(sfelder['⚙ Google Place ID'], storeJ, storeT)) || '');
const mapsUrl = placeId || storeName
  ? ('https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(storeName) +
     '&query_place_id=' + encodeURIComponent(placeId)).replace(/&/g, '&amp;')
  : '';

// {Saldoabruf}: kein neuer Geldwert, nur der Vergleich zweier gelesener.
// created  → die Auszahlung steckt noch nicht in »Ausgezahlt«  → Betrag ≥ Offen
// settled  → sie ist bereits abgezogen                          → Betrag ≥ Offen + Betrag
let saldoabruf = '';
if (saldoModus) {
  const betrag = zahl(roh('Betrag'));
  const offen  = zahl(roh('Offen'));
  if (betrag !== null && offen !== null) {
    const grenze = (saldoModus === 'settled') ? (offen + betrag) : offen;
    saldoabruf = (betrag >= grenze - 0.005) ? 'Voller Saldo' : 'Teilbetrag';
  }
}

function wert(token) {
  if (token === 'Vorname')    return vorname;
  if (token === 'Maps-URL')   return mapsUrl;
  if (token === 'Saldoabruf') return saldoabruf;
  return flach(roh(token));
}

// ── Rendern einer Vorlage ───────────────────────────────────────────────

function render(vorlage) {
  if (!vorlage) return '';

  // 1. Zeilen-Modifier {leer FELD} / {gesetzt FELD}
  const zeilen = String(vorlage).split('\n');
  const behalten = [];
  for (let i = 0; i < zeilen.length; i++) {
    const m = zeilen[i].match(/^\{(leer|gesetzt) ([^{}\n]+)\}/);
    if (m) {
      const leer = istLeer(roh(m[2].trim()));
      const ok = (m[1] === 'leer') ? leer : !leer;
      if (!ok) continue;
      behalten.push(zeilen[i].slice(m[0].length));
    } else {
      behalten.push(zeilen[i]);
    }
  }

  // 2. Token ersetzen
  let text = behalten.join('\n').replace(/\{([^{}"\n]+)\}/g, function (_, rohToken) {
    const absolut = rohToken.indexOf('abs ') === 0;
    const token = absolut ? rohToken.slice(4).trim() : rohToken.trim();
    let v = wert(token);
    if (v === '' || v === null || v === undefined) return '';
    if (token === 'Maps-URL') return v;               // bereits escaped
    if (geld.indexOf(token) !== -1) {
      const n = zahl(v);
      if (n !== null) return esc(euro(absolut ? Math.abs(n) : n));
    } else if (absolut) {
      const n = zahl(v);
      if (n !== null) v = Math.abs(n);
    }
    if (/^\d{4}-\d{2}-\d{2}$/.test(String(v))) {
      const t = String(v).split('-');
      v = t[2] + '.' + t[1] + '.' + t[0];
    }
    return esc(v);
  });

  // 3. Zeile, die Token trug und deren Token alle leer blieben, faellt weg
  text = text.split('\n').filter(function (z, i) {
    const roh = behalten[i];
    if (roh === undefined) return true;
    const hatte = /\{[^{}"\n]+\}/.test(roh);
    if (!hatte) return true;
    return z.replace(/[^\wÄÖÜäöüß]/g, '') !== roh.replace(/\{[^{}"\n]+\}/g, '').replace(/[^\wÄÖÜäöüß]/g, '');
  }).join('\n');

  // 4. Leeres Segment entfernt sich samt ' · '
  text = text.split('\n').map(function (z) {
    if (z.indexOf(' · ') === -1) return z;
    return z.split(' · ').filter(function (s) { return s.trim() !== ''; }).join(' · ');
  }).join('\n');

  // 5. Leerzeilen glätten, die durch weggefallene Zeilen entstanden sind
  text = text.replace(/[ \t]+$/gm, '').replace(/\n{3,}/g, '\n\n').replace(/^\n+|\n+$/g, '');

  // 6. Betreffzeile generell fett — kein Template trägt <b> in Zeile 1
  const z = text.split('\n');
  z[0] = '<b>' + z[0] + '</b>';
  return z.join('\n');
}

// ── Zielangaben ─────────────────────────────────────────────────────────

const vchat = String(flach(ausEbene(vfelder['⚙ Telegram ID'], vertriebler, {})) || '');
const cchat = String(flach(ausEbene(sfelder['⚙ Telegram ID'], storeJ, storeT)) || '');

let foto = '';
if (input.foto) {
  const anhang = recJ[input.foto];
  if (Array.isArray(anhang) && anhang.length && anhang[0] && anhang[0].url) foto = anhang[0].url;
}

const text  = render(input.vorlage);
const vtext = render(input.vvorlage);
const ctext = render(input.cvorlage);

// Explizite Schaltflaggen statt Leerstring-Vergleichen in den Router-Filtern.
return {
  text: text, vtext: vtext, ctext: ctext,
  vchat: vchat, cchat: cchat, foto: foto,
  ops:        text  ? '1' : '0',
  vtrb:      (vtext && vchat) ? '1' : '0',
  city_foto: (ctext && cchat && foto) ? '1' : '0',
  city_text: (ctext && cchat && !foto) ? '1' : '0'
};
